<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Mini Spreadsheet</title>
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: Arial, sans-serif;
  padding: 16px;
  background: #f0f2f5;
  min-width: 640px;
  min-height: 500px;
}
h1 { font-size: 17px; color: #222; margin-bottom: 10px; }
.toolbar { margin-bottom: 10px; }
#export {
  padding: 6px 16px;
  background: #1a73e8;
  color: #fff;
  border: none;
  border-radius: 4px;
  font-size: 13px;
  cursor: pointer;
}
#export:hover { background: #1558b0; }
.grid-wrap {
  display: inline-block;
  overflow: auto;
  border: 1px solid #bbb;
  background: #fff;
  min-width: 600px;
  min-height: 300px;
}
table { border-collapse: collapse; }
th {
  background: #e8eaf6;
  border: 1px solid #c0c2c8;
  padding: 5px 8px;
  font-size: 12px;
  font-weight: 600;
  text-align: center;
  color: #333;
  min-width: 80px;
  user-select: none;
}
th.corner { min-width: 38px; }
